tool_use_result.originalFile:
/* Tallyline — shared stylesheet. Tokens and decisions: see DESIGN.md */

:root {
  color-scheme: light;
  --bg: oklch(0.975 0.005 250);
  --surface: oklch(1 0 0);
  --ink: oklch(0.24 0.015 250);
  --muted: oklch(0.46 0.015 250);
  --line: oklch(0.6 0.012 250);          /* control edges, 3.9:1 on surface */
  --line-soft: oklch(0.91 0.006 250);    /* dividers only, never a control edge */
  --accent: oklch(0.47 0.1 170);
  --accent-hover: oklch(0.41 0.09 170);
  --accent-soft: oklch(0.96 0.025 170);
  --danger: oklch(0.51 0.19 27);
  --danger-hover: oklch(0.45 0.17 27);
  --danger-soft: oklch(0.965 0.018 27);
  --ring: var(--accent);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem; --s7: 4rem;
  --r-control: 6px;
  --r-panel: 10px;
  --savebar-h: 4.5rem;

  --z-sticky: 10;
  --z-dialog: 30;

  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 100%;
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  scroll-padding-bottom: calc(var(--savebar-h) + var(--s4));
}

*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; min-height: 100dvh; }
::selection { background: var(--accent-soft); color: var(--ink); }
input, select, textarea, button { font: inherit; color: inherit; }

h1, h2, h3 { line-height: 1.2; text-wrap: balance; margin: 0; }
h1 { font-size: 1.728rem; font-weight: 650; letter-spacing: -0.015em; }
h2 { font-size: 1.2rem; font-weight: 620; }
p { margin: 0; }

a { color: var(--accent); text-underline-offset: 0.2em; }
a:hover { color: var(--accent-hover); }

:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link { position: absolute; inset-inline-start: var(--s4); top: -3rem; }
.skip-link:focus { top: var(--s2); outline: 2px solid var(--ring); outline-offset: 2px; background: var(--surface); padding: var(--s2) var(--s3); z-index: var(--z-dialog); }

/* ---------- Wordmark ---------- */
.wordmark {
  display: inline-flex; align-items: center; gap: var(--s2);
  font-weight: 700; font-size: 1.05rem; letter-spacing: -0.01em; color: var(--ink); text-decoration: none;
}
.wordmark svg { width: 1.4rem; height: 1.4rem; color: var(--accent); }

/* ---------- Signature: the tally chip ---------- */
/* One shape counts every pending state: unsaved changes, errors, per-section errors. */
.tally {
  display: inline-flex; align-items: center; gap: 0.35em;
  padding: 0.125em 0.5em;
  border: 1px solid currentColor;
  border-radius: 4px;
  font-size: 0.833rem; font-weight: 600; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  vertical-align: 0.1em;
  color: var(--ink); background: var(--bg);
}
.tally--error { color: var(--danger); background: var(--danger-soft); }
.tally svg { width: 1em; height: 1em; flex: none; }
.tally[hidden] { display: none; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s2);
  min-height: 2.75rem; padding: 0 var(--s4);
  border: 1px solid var(--line); border-radius: var(--r-control);
  background: var(--surface); color: var(--ink);
  font-weight: 560; white-space: nowrap; cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn--primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn--danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn--danger-outline { color: var(--danger); border-color: var(--danger); }
.btn--quiet { border-color: transparent; background: transparent; }
@media (hover: hover) {
  .btn:hover { background: var(--bg); }
  .btn--primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
  .btn--danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }
  .btn--danger-outline:hover { background: var(--danger-soft); }
}
.btn:active { background: var(--line-soft); }
.btn--primary:active { background: var(--accent-hover); }
.btn--danger:active { background: var(--danger-hover); }
.btn[aria-disabled="true"] { cursor: progress; opacity: 0.75; }
.btn .spinner {
  width: 1em; height: 1em; border-radius: 50%;
  border: 2px solid currentColor; border-inline-end-color: transparent;
  animation: spin 700ms linear infinite;
}
.btn:not([aria-disabled="true"]) .spinner { display: none; }
@keyframes spin { to { transform: rotate(1turn); } }

/* ---------- Fields ---------- */
.field { display: grid; gap: var(--s1); }
.field + .field, .pair + .field, .field + .pair { margin-top: var(--s5); }
label, .label { font-weight: 560; }
.opt { font-weight: 400; color: var(--muted); }
.hint { color: var(--muted); font-size: 0.9rem; }

.input, select.input {
  width: 100%; min-height: 2.75rem;
  padding: var(--s2) var(--s3);
  font-size: 1rem;
  border: 1px solid var(--line); border-radius: var(--r-control);
  background: var(--surface);
  caret-color: var(--accent);
  transition: border-color 150ms ease-out;
}
.input:focus-visible { outline-offset: 1px; border-color: var(--accent); }
.input[aria-invalid="true"] { border-color: var(--danger); border-width: 2px; padding: calc(var(--s2) - 1px) calc(var(--s3) - 1px); }
.input--code { font-variant-numeric: tabular-nums; letter-spacing: 0.01em; }

.error {
  display: flex; gap: var(--s2); align-items: flex-start;
  color: var(--danger); font-weight: 560; font-size: 0.95rem;
  overflow-wrap: anywhere;
}
.error svg { width: 1.1em; height: 1.1em; flex: none; margin-top: 0.2em; }
.error[hidden] { display: none; }

.pair { display: grid; gap: var(--s5) var(--s4); }
.pair > .field + .field { margin-top: 0; }
@media (min-width: 30rem) { .pair { grid-template-columns: 1fr 1fr; } }

.check { display: grid; grid-template-columns: auto 1fr; gap: 0 var(--s3); align-items: start; padding-block: var(--s2); cursor: pointer; }
.check input { width: 1.5rem; height: 1.5rem; margin: 0; accent-color: var(--accent); cursor: pointer; }
.check .hint { grid-column: 2; font-weight: 400; }

/* ---------- Banners ---------- */
.banner {
  display: flex; gap: var(--s3); align-items: flex-start;
  padding: var(--s3) var(--s4);
  border: 1px solid currentColor; border-radius: var(--r-control);
}
.banner svg { width: 1.2rem; height: 1.2rem; flex: none; margin-top: 0.15rem; }
.banner--error { color: var(--danger); background: var(--danger-soft); }
.banner--error p { color: var(--ink); }
.banner--ok { color: var(--accent); background: var(--accent-soft); }
.banner--ok p { color: var(--ink); }
.banner[hidden] { display: none; }

/* ==========================================================
   Sign in
   ========================================================== */
.auth { display: grid; place-items: start center; padding: var(--s7) var(--s4); }
.auth-inner { width: 100%; max-width: 24rem; display: grid; gap: var(--s5); }
.auth-panel { background: var(--surface); border: 1px solid var(--line-soft); border-radius: var(--r-panel); padding: var(--s5); display: grid; gap: var(--s5); }
.auth-panel h1 { font-size: 1.44rem; }
.label-row { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s3); flex-wrap: wrap; }
.label-row a { font-size: 0.9rem; padding-block: 0.2rem; }
.password-wrap { position: relative; }
.password-wrap .input { padding-inline-end: 5rem; }
.password-toggle {
  position: absolute; inset-inline-end: 0.25rem; top: 50%; transform: translateY(-50%);
  min-height: 2.25rem; min-width: 4rem; padding: 0 var(--s3);
  border: 0; border-radius: 4px; background: transparent; color: var(--accent); font-weight: 560; cursor: pointer;
}
@media (hover: hover) { .password-toggle:hover { background: var(--accent-soft); } }
.auth-panel .btn--primary { width: 100%; }

/* ==========================================================
   App shell + settings
   ========================================================== */
.topbar {
  display: flex; align-items: center; gap: var(--s4); flex-wrap: wrap;
  padding: var(--s3) var(--s5);
  background: var(--surface); border-bottom: 1px solid var(--line-soft);
}
.topbar .ws { color: var(--muted); overflow-wrap: anywhere; min-width: 0; }
.topbar .spacer { flex: 1; }

.page { max-width: 64rem; margin: 0 auto; padding: var(--s6) var(--s5) var(--s7); }
.page-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s4); flex-wrap: wrap; margin-bottom: var(--s6); }
.page-head p { color: var(--muted); margin-top: var(--s2); }

.layout { display: grid; gap: var(--s6); grid-template-columns: minmax(0, 1fr); }
.layout > .main { min-width: 0; max-width: 40rem; }
/* Help comes first in the DOM: stacked above the form when narrow, placed beside it when wide. */
@media (min-width: 64rem) {
  .layout.help-open { grid-template-columns: minmax(0, 40rem) 20rem; justify-content: space-between; }
  .layout.help-open > .main { grid-column: 1; grid-row: 1; }
  .layout.help-open > .help { grid-column: 2; grid-row: 1; }
}

/* Help panel: non-modal, no scrim, stays beside the form */
.help {
  align-self: start;
  background: var(--surface); border: 1px solid var(--line-soft); border-radius: var(--r-panel);
  padding: var(--s5);
}
@media (min-width: 64rem) { .help { position: sticky; top: var(--s5); max-height: calc(100dvh - 2 * var(--s5)); overflow-y: auto; } }
.help[hidden] { display: none; }
.help-head { display: flex; justify-content: space-between; align-items: center; gap: var(--s3); margin-bottom: var(--s3); }
.help h3 { font-size: 1rem; font-weight: 620; margin-top: var(--s5); margin-bottom: var(--s1); }
.help p, .help li { color: var(--muted); font-size: 0.93rem; }
.help p + p, .help ul + p { margin-top: var(--s2); }
.help ul { padding-inline-start: 1.1rem; margin: var(--s1) 0 0; }
.help code { font-size: 0.88em; color: var(--ink); overflow-wrap: anywhere; }

/* Error summary */
.summary {
  margin-bottom: var(--s6);
  padding: var(--s4) var(--s5);
  border: 2px solid var(--danger); border-radius: var(--r-panel);
  background: var(--surface);
}
.summary:focus-visible { outline-offset: 3px; }
.summary h2 { display: flex; align-items: center; gap: var(--s3); flex-wrap: wrap; font-size: 1.1rem; }
.summary p { margin-top: var(--s2); color: var(--muted); }
.summary ul { margin: var(--s3) 0 0; padding-inline-start: 1.1rem; display: grid; gap: var(--s1); }
.summary a { color: var(--danger); font-weight: 560; }
.summary[hidden] { display: none; }

/* Sections: separated by rules, not cards */
.section { border: 0; margin: 0; padding: 0 0 var(--s6); min-width: 0; }
.section + .section { border-top: 1px solid var(--line-soft); padding-top: var(--s6); }
.section legend { padding: 0; float: left; width: 100%; margin-bottom: var(--s4); font-size: 1.2rem; font-weight: 620; line-height: 1.2; }
.section legend .tally { margin-inline-start: var(--s2); }
.section legend + * { clear: both; }
.section .section-intro { color: var(--muted); margin-top: calc(-1 * var(--s2)); margin-bottom: var(--s5); }
.section-intro + .check { margin-top: calc(-1 * var(--s2)); }

/* Sticky save bar: always rendered, so nothing jumps in or out */
.savebar {
  position: sticky; bottom: 0; z-index: var(--z-sticky);
  min-height: var(--savebar-h);
  display: flex; align-items: center; gap: var(--s3); flex-wrap: wrap;
  padding: var(--s3) 0;
  background: var(--bg);
  border-top: 1px solid var(--line);
}
.savebar .state { flex: 1; min-width: 10rem; display: flex; align-items: center; gap: var(--s3); flex-wrap: wrap; }
.savebar .state-text { color: var(--muted); }
.savebar .actions { display: flex; gap: var(--s2); }
.savebar #save-btn { min-width: 9.5rem; }
.savebar .banner { flex-basis: 100%; }
.savebar .banner .btn { margin-inline-start: auto; min-height: 2.25rem; color: var(--ink); }
[data-clean] .btn-discard { visibility: hidden; }

/* Danger zone */
.danger-zone {
  margin-top: var(--s7);
  border: 1px solid var(--danger); border-radius: var(--r-panel);
  padding: var(--s5);
  display: flex; gap: var(--s4) var(--s5); align-items: center; justify-content: space-between; flex-wrap: wrap;
}
.danger-zone h2 { color: var(--danger); }
.danger-zone p { color: var(--muted); margin-top: var(--s1); max-width: 34rem; }

/* Delete dialog */
dialog {
  width: min(32rem, calc(100vw - 2 * var(--s4)));
  max-height: calc(100dvh - 2 * var(--s4));
  padding: var(--s5);
  border: 1px solid var(--line); border-radius: var(--r-panel);
  background: var(--surface); color: var(--ink);
  box-shadow: 0 1.5rem 3rem -1rem oklch(0.24 0.015 250 / 0.35);
  opacity: 1; transform: none;
  transition: opacity 200ms cubic-bezier(0.22, 1, 0.36, 1), transform 200ms cubic-bezier(0.22, 1, 0.36, 1),
              overlay 200ms allow-discrete, display 200ms allow-discrete;
}
@starting-style { dialog[open] { opacity: 0; transform: scale(0.97); } }
dialog::backdrop { background: oklch(0.24 0.015 250 / 0.5); }
dialog h2 { font-size: 1.3rem; overflow-wrap: anywhere; }
dialog .consequences { margin: var(--s4) 0 0; padding-inline-start: 1.2rem; display: grid; gap: var(--s2); }
dialog .consequences + p { margin-top: var(--s4); }
dialog .field { margin-top: var(--s5); }
dialog .confirm-name { font-weight: 700; overflow-wrap: anywhere; }
dialog .actions { display: flex; justify-content: flex-end; gap: var(--s2); flex-wrap: wrap; margin-top: var(--s5); }
dialog #delete-confirm { min-width: 11rem; }

@media (max-width: 30rem) {
  .page { padding-inline: var(--s4); }
  .topbar { padding-inline: var(--s4); }
  .savebar .actions { width: 100%; }
  .savebar .actions .btn { flex: 1; }
  .savebar #save-btn { min-width: 0; }
}

/* Reduced motion: drop movement, keep the state change visible */
@media (prefers-reduced-motion: reduce) {
  dialog { transition: opacity 150ms ease-out, overlay 150ms allow-discrete, display 150ms allow-discrete; }
  @starting-style { dialog[open] { transform: none; } }
  .btn .spinner { animation-duration: 2s; }
}

