const f=(n)=>n<=0.0031308?12.92*n:1.055*Math.pow(n,1/2.4)-0.055;
const o=(L,C,H)=>{const h=H*Math.PI/180,a=C*Math.cos(h),b=C*Math.sin(h);
  const l=(L+0.3963377774*a+0.2158037573*b)**3, m=(L-0.1055613458*a-0.0638541728*b)**3,
        s=(L-0.0894841775*a-1.2914855480*b)**3;
  return [ 4.0767416621*l-3.3077115913*m+0.2309699292*s,
          -1.2684380046*l+2.6097574011*m-0.3413193965*s,
          -0.0041960863*l-0.7034186147*m+1.7076147010*s]
        .map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
const lum=([r,g,b])=>{const c=[r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];};
const ratio=(A,B)=>{const [x,y]=[lum(A),lum(B)].sort((p,q)=>q-p);return +((x+0.05)/(y+0.05)).toFixed(2);};
const T={bg:o(0.975,0.005,250),surface:o(1,0,0),ink:o(0.24,0.015,250),muted:o(0.46,0.015,250),line:o(0.6,0.012,250),
 soft:o(0.91,0.006,250),accent:o(0.47,0.1,170),danger:o(0.51,0.19,27),dangerSoft:o(0.965,0.018,27),accentSoft:o(0.96,0.025,170),white:[255,255,255]};
const P=[['ink','bg'],['ink','surface'],['muted','surface'],['muted','bg'],['line','surface'],['line','bg'],['accent','surface'],['accent','bg'],
['white','accent'],['danger','surface'],['danger','bg'],['danger','dangerSoft'],['white','danger'],['ink','accentSoft'],['accent','accentSoft'],['ink','dangerSoft'],['soft','surface']];
for(const [a,b] of P) console.log(a.padEnd(10),'on',b.padEnd(10),ratio(T[a],T[b]));
console.log(Object.entries(T).map(([k,v])=>k+':'+v).join('  '));
